import sys
from typing import List

def max_rectangle_area(N: int, A: List[int]) -> int:
    A.sort()
    max_area = 0

    for i in range(N-3):
        for j in range(i+1, N-2):
            if A[i] * A[j] > max_area:
                for k in range(j+1, N-1):
                    if A[k] == A[j]:
                        continue
                    for l in range(k+1, N):
                        if A[l] == A[k]:
                            continue
                        if A[i] + A[j] == A[k] + A[l]:
                            max_area = max(max_area, A[i] * A[j])

    return max_area

